import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import ProductCard from "./ProductCard";
import "./global.css";

export default function Home() {
  const [products, setProducts] = useState([]);

  useEffect(() => {
    fetch("http://localhost:5001/api/products")
      .then((res) => res.json())
      .then((data) => setProducts(data))
      .catch((err) => console.log(err));
  }, []);

  return (
    <div className="home-page">

      {/* HERO SECTION */}
      <div
  className="hero-section"
  style={{
    backgroundImage: "url('https://images.unsplash.com/photo-1523381210434-271e8be1f52b?w=1400')",
    backgroundSize: "cover",
    backgroundPosition: "center",
    height: "300px",
    borderRadius: "12px",
    display: "flex",
    flexDirection: "column",
    justifyContent: "center",
    alignItems: "center",
    color: "white",
    textShadow: "0 2px 10px rgba(0,0,0,0.4)",
  }}
>
  <h1>Welcome to Rewear</h1>
  <p className="tagline">Buy • Sell • Swap — A Sustainable Marketplace 🌱</p>
</div>


      {/* ACTION BAR */}
      <div className="action-bar">
        <div className="action-left">
          <Link to="/">Buy / Swap</Link>
        </div>

        <div className="action-right">
          <Link to="/create">Sell</Link>
        </div>
      </div>

      {/* PRODUCTS SECTION */}
      <h2 className="section-title">Available Products</h2>
      <div className="product-grid">
        {products.length > 0 ? (
          products.map((p) => <ProductCard key={p._id} product={p} />)
        ) : (
          <p style={{ textAlign: "center", width: "100%" }}>No products yet.</p>
        )}
      </div>
    </div>
  );
}
